    double dx = a.x - b.x;
    double dy = a.y - b.y;
    double dz = a.z - b.z;
    return sqrt(dx * dx + dy * dy + dz * dz);
}

// Function to calculate the angle between two vectors
double angleBetweenVectors(Point3D a, Point3D b, Point3D c) {
    // Vectors AB and AC
    Point3D ab = {a.x - b.x, a.y - b.y, a.z - b.z};
    Point3D ac = {a.x - c.x, a.y - c.y, a.z - c.z};

    double dot = ab.x * ac.x + ab.y * ac.y + ab.z * ac.z;
    double len_ab = length(a, b);
    double len_ac = length(a, c);

    if (len_ab == 0 || len_ac == 0) return 0;

    return acos(dot / (len_ab * len_ac));
}

