### 📦 1.2 Java 代码示例：JSON 转 XML

```java
import ca.uhn.fhir.context.FhirContext;
import ca.uhn.fhir.parser.IParser;
import org.hl7.fhir.r4.model.Bundle;
import org.hl7.fhir.r4.model.Patient;

import java.io.StringReader;
import java.io.StringWriter;

public class FhirJsonToXmlConverter {

    public static String convertJsonToXml(String json) {
        FhirContext ctx = FhirContext.forR4(); // 使用 R4 版本
        IParser parser = ctx.newJsonParser();

        // 解析 JSON 字符串为 FHIR 资源对象
        Patient patient = parser.parseResource(Patient.class, new StringReader(json));

        // 转换为 XML
        IParser xmlParser = ctx.newXmlParser();
        StringWriter writer = new StringWriter();
        xmlParser.setPrettyPrint(true);
        xmlParser.encodeResourceToString(patient, writer);

        return writer.toString();
    }

    public static void main(String[] args) {
        String json = "{\n" +
                "  \"resourceType\": \"Patient\",\n" +
                "  \"id\": \"123\",\n" +
                "  \"name\": [{\"family\": \"Smith\", \"given\": [\"John\"]}]\n" +
                "}";
        String xml = convertJsonToXml(json);
        System.out.println(xml);
    }
}
```

